public:
    int minWastedSpace(vector<int>& packages, vector<vector<int>>& boxes) {
        sort(packages.begin(), packages.end());
        int n = packages.size();
        long long pkgSum = 0;
        for (int p : packages) pkgSum += p;

        long long INF = 1e18;
        long long minTotalBox = INF;

        for (auto& supplier : boxes) {
            sort(supplier.begin(), supplier.end());
            if (supplier.back() < packages.back()) continue;

            long long currBoxSum = 0;
            int prevIdx = 0;
            for (int b : supplier) {
                int idx = upper_bound(packages.begin(), packages.end(), b) - packages.begin();
                long long count = idx - prevIdx;
                currBoxSum += count * b;
                prevIdx = idx;
                if (idx == n) break;
            }
            minTotalBox = min(minTotalBox, currBoxSum);
        }
        return (minTotalBox == INF) ? -1 : (minTotalBox - pkgSum) % 1000000007;
