import java.util.*;

class Solution {
    private int upperBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    public int minWastedSpace(int[] packages, int[][] boxes) {
        Arrays.sort(packages);
        int n = packages.length;
        long pkgSum = 0;
        for (int p : packages) pkgSum += p;

        long INF = (long)1e18;
        long minTotalBox = INF;

        for (int[] supplier : boxes) {
            Arrays.sort(supplier);
            if (supplier[supplier.length - 1] < packages[n - 1]) continue;

            long currBoxSum = 0;
            int prevIdx = 0;
            for (int b : supplier) {
                int idx = upperBound(packages, b);
                long count = idx - prevIdx;
                currBoxSum += count * b;
                prevIdx = idx;
                if (idx == n) break;
            }
            minTotalBox = Math.min(minTotalBox, currBoxSum);
        }
        return (minTotalBox == INF) ? -1 : (int)((minTotalBox - pkgSum) % 1_000_000_007L);
    }
}

/**
 * @param {number[]} packages
 * @param {number[][]} boxes
 * @return {number}
 */
var minWastedSpace = function(packages, boxes) {
    packages.sort((a, b) => a - b);
    const n = packages.length;
    let pkgSum = 0n;
    for (const p of packages) pkgSum += BigInt(p);

    const upperBound = (arr, target) => {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    const INF = 1e18;
    let minTotalBox = BigInt(INF);

    for (const supplier of boxes) {
        supplier.sort((a, b) => a - b);
        if (supplier[supplier.length - 1] < packages[n - 1]) continue;

        let currBoxSum = 0n;
        let prevIdx = 0;
        for (const b of supplier) {
            const idx = upperBound(packages, b);
            const count = BigInt(idx - prevIdx);
            currBoxSum += count * BigInt(b);
            prevIdx = idx;
            if (idx === n) break;
        }
        if (currBoxSum < minTotalBox) minTotalBox = currBoxSum;
    }

    if (minTotalBox >= BigInt(INF)) return -1;
    return Number((minTotalBox - pkgSum) % 1000000007n);
};
